<?php
require_once __DIR__.'/includes/layout.php';
require_once __DIR__.'/includes/import_csv.php';
if($_SERVER['REQUEST_METHOD']==='POST' && ($_POST['action']??'')==='import_csv') importer('thai','thai.php');
require_role(['SO']);
if($_SERVER['REQUEST_METHOD']==='POST')task('thai.php',function(PDO $db,array $u){if($u['vai_tro']!=='SO')throw new RuntimeException('Chỉ Sở GD&ĐT được nhập và phê duyệt chỉ tiêu.');$act=val('action');$ky=required_val('ma_ky_thi');$truong=required_val('ma_truong');$he=required_val('ma_he');$db->beginTransaction();try{
 if($act==='save'){$so=filter_var(val('so_luong'),FILTER_VALIDATE_INT);if($so===false||$so<0)throw new RuntimeException('Chỉ tiêu không hợp lệ.');$q=$db->prepare('SELECT kha_nang_tiep_nhan FROM truong_thpt WHERE ma_truong=? FOR UPDATE');$q->execute([$truong]);$capacity=$q->fetchColumn();if($capacity===false)throw new RuntimeException('Trường THPT không tồn tại.');$q=$db->prepare('SELECT COALESCE(SUM(so_luong),0) FROM chi_tieu WHERE ma_ky_thi=? AND ma_truong=? AND ma_he<>?');$q->execute([$ky,$truong,$he]);if($so+(int)$q->fetchColumn()>(int)$capacity)throw new RuntimeException('Tổng chỉ tiêu vượt khả năng tiếp nhận.');$q=$db->prepare('SELECT trang_thai FROM chi_tieu WHERE ma_ky_thi=? AND ma_truong=? AND ma_he=? FOR UPDATE');$q->execute([$ky,$truong,$he]);if($q->fetchColumn()==='DA_DUYET')throw new RuntimeException('Chỉ tiêu đã duyệt được khóa chỉnh sửa.');$q=$db->prepare("INSERT INTO chi_tieu(ma_ky_thi,ma_truong,ma_he,so_luong) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE so_luong=VALUES(so_luong)");$q->execute([$ky,$truong,$he,$so]);}
 elseif($act==='approve'){$q=$db->prepare("UPDATE chi_tieu SET trang_thai='DA_DUYET',nguoi_duyet=?,ngay_duyet=NOW() WHERE ma_ky_thi=? AND ma_truong=? AND ma_he=? AND trang_thai='DU_KIEN'");$q->execute([$u['id'],$ky,$truong,$he]);if(!$q->rowCount())throw new RuntimeException('Không có chỉ tiêu dự kiến để duyệt.');}
 else throw new RuntimeException('Thao tác không hợp lệ.');audit($db,$u['id'],'CHI_TIEU',$act.' '.$ky.' / '.$truong.' / '.$he);$db->commit();}catch(Throwable $e){$db->rollBack();throw $e;}});
page_start('Phân bổ chỉ tiêu tuyển sinh','thai');echo '<div class="note">QT05: Kiểm tra tổng chỉ tiêu không vượt sức tiếp nhận. Chỉ Sở phê duyệt; dữ liệu <b>Đã duyệt</b> không được sửa.</div><div class="panel"><h2>Nhập / cập nhật dự kiến</h2>';form_open();echo '<input type="hidden" name="action" value="save">';select_field('ma_ky_thi','Kỳ thi','SELECT ma_ky_thi,ten_ky_thi FROM ky_thi ORDER BY nam_tuyen_sinh DESC','ma_ky_thi','ten_ky_thi');select_field('ma_truong','Trường THPT','SELECT ma_truong,ten_truong FROM truong_thpt ORDER BY ten_truong','ma_truong','ten_truong');select_field('ma_he','Hệ xét tuyển','SELECT ma_he,ten_he FROM he_xet_tuyen','ma_he','ten_he');field('so_luong','Số lượng chỉ tiêu','number',true,'min="0" step="1"');form_close('Lưu dự kiến');echo '</div><div class="panel"><h2>Phê duyệt một chỉ tiêu</h2>';form_open();echo '<input type="hidden" name="action" value="approve">';select_field('ma_ky_thi','Kỳ thi','SELECT ma_ky_thi,ten_ky_thi FROM ky_thi','ma_ky_thi','ten_ky_thi');select_field('ma_truong','Trường THPT','SELECT ma_truong,ten_truong FROM truong_thpt','ma_truong','ten_truong');select_field('ma_he','Hệ xét tuyển','SELECT ma_he,ten_he FROM he_xet_tuyen','ma_he','ten_he');form_close('Phê duyệt và khóa');echo '</div><div class="panel"><h2>Chỉ tiêu đã nhập</h2>';table_rows(db()->query('SELECT c.ma_ky_thi,t.ten_truong,h.ten_he,c.so_luong,c.trang_thai FROM chi_tieu c JOIN truong_thpt t ON c.ma_truong=t.ma_truong JOIN he_xet_tuyen h ON c.ma_he=h.ma_he ORDER BY c.ma_ky_thi,c.ma_truong')->fetchAll(),['Kỳ thi','Trường','Hệ','Chỉ tiêu','Trạng thái']);echo '</div>';import_panel('thai','Chỉ tiêu tuyển sinh');page_end();
